def modular_sum(arr, m, n): 
    dp = [False] * (n + 1) 
    dp[0] = True
    for i in range(0, n): 
        for j in range(m): 
            if (i - arr[j] >= 0 and dp[i - arr[j]] == True): 
                dp[i] = True
                break
    return dp[n]
