def get_lcm(arr):
    if len(arr) < 2:
        return max(arr)
    gcd = arr[0]
    for i in range(1, len(arr)):
        gcd = math.gcd(gcd, arr[i])
    lcm = abs(arr[0] * arr[1]) // gcd
    for i in range(2, len(arr)):
        lcm = lcm // arr[i] * arr[i]
    return lcm
```

