    lis = [1] * n
    lds = [1] * n
    for i in range(1,n):
        for j in range(i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1
    for i in range(n-2,-1,-1):
        for j in range(n):
            if arr[i] > arr[j] and lds[i] < lds[j] + 1:
                lds[i] = lds[j] + 1
    res = 0
    for i in range(n):
        res = max(res,lis[i] + lds[i] - 1)
