def get_pairs_count(arr, n, sum):
    count = 0
    arr.sort()
    for i in range(0, n-1):
        left = i + 1
        right = n - 1
        while left < right:
            total = arr[i] + arr[left] + arr[right]
            if total == sum:
                count += 1
                break
            elif total < sum:
                left += 1
            else:
                right -= 1
    return count
```

