def min_coins(coins, m, V):
    dp = [0 for i in range(V + 1)]
    dp[0] = 0
    for i in range(1, m + 1):
        for j in range(V, -1, -1):
            if coins[i - 1] <= j:
                dp[j] = min(dp[j], dp[j - coins[i - 1]] + 1)
            else:
                dp[j] = dp[j]
    return dp[V]
