def find_kth(arr1, arr2, m, n, k):
    i = m - 1
    j = n - 1
    count = 0
    while (i >= 0 and j >= 0):
        if (arr1[i] == arr2[j]):
            count += 1
            return arr1[i]
            break
        elif (arr1[i] > arr2[j]):
            count += 1
            j -= 1
        else:
            count += 1
            i += 1
    if (count < k):
        return arr1[i + 1]
    else:
        return arr2[j + 1]
```

